buttons.css:
.button {
  background-color: rgb(44, 72, 220);
  color: rgb(255, 255, 255);
  font-size: 16px;
  font-weight: 300;
  padding-top: 0px;
  padding-right: 0px;
  border-radius: 0px;
}

cards.css:
.card {
  background-color: rgb(32, 34, 46);
  border-radius: 0px;
  box-shadow: rgba(0, 0, 0, 0.08) 0px 2px 8px 0px;
  padding-top: 0px;
  padding-right: 0px;
}

navigation.css:
.navigation {
  background-color: rgb(240, 243, 255);
  color: rgb(32, 34, 46);
  padding-top: 0px;
  padding-bottom: 0px;
  padding-left: 0px;
  padding-right: 0px;
  position: static;
}

footer.css:
.footer {
  background-color: rgb(32, 34, 46);
  color: rgb(26, 26, 26);
  padding-top: 0px;
  padding-bottom: 0px;
  font-size: 16px;
}

dropdowns.css:
.dropdown {
  background-color: rgb(32, 34, 46);
  border-radius: 0px;
  border-color: rgb(255, 255, 255);
  padding-top: 0px;
}

badges.css:
.badge {
  color: rgb(174, 176, 183);
  font-size: 12px;
  font-weight: 300;
  padding-top: 0px;
  padding-right: 0px;
  border-radius: 0px;
}

tabs.css:
.tab {
  color: rgb(255, 255, 255);
  font-size: 18px;
  font-weight: 300;
  padding-top: 0px;
  padding-right: 0px;
  border-color: rgb(255, 255, 255);
  border-radius: 0px;
}

